package io.github.altarosrs.burneralarm;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;

public class MarrentillTrackerOverlay extends OverlayPanel
{
	private final BurnerAlarmPlugin plugin;
	private final BurnerAlarmConfig config;

	@Inject
	private MarrentillTrackerOverlay(BurnerAlarmPlugin plugin, BurnerAlarmConfig config)
	{
		super(plugin);
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.TOP_CENTER);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!plugin.shouldShowMarrentillOverlay())
		{
			return null;
		}

		panelComponent.getChildren().clear();
		panelComponent.setPreferredSize(new Dimension(220, 0));

		Color baseColor = config.marrentillGameMessageColor();
		panelComponent.setBackgroundColor(new Color(
			baseColor.getRed(), baseColor.getGreen(), baseColor.getBlue(), 200));

		panelComponent.getChildren().add(LineComponent.builder()
			.left("Marrentill Stock Low!")
			.leftColor(Color.WHITE)
			.build());

		String message = plugin.getUnnotedMarrentillCount() == 1
			? "Only 1 unnoted Marrentill left."
			: "Out of unnoted Marrentills.";
		panelComponent.getChildren().add(LineComponent.builder()
			.left(message)
			.leftColor(Color.WHITE)
			.build());

		return super.render(graphics);
	}
}

