package io.github.altarosrs.burneralarm;

import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.TitleComponent;

public class POHGuestOverlay extends OverlayPanel
{
	private final BurnerAlarmPlugin plugin;
	private final BurnerAlarmConfig config;

	@Inject
	public POHGuestOverlay(BurnerAlarmPlugin plugin, BurnerAlarmConfig config)
	{
		super(plugin);
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.TOP_LEFT);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.pohGuestTrackerEnabled() || !plugin.isInPOH() || plugin.getGuestCount() < 0)
		{
			return null;
		}

		panelComponent.getChildren().clear();
		panelComponent.getChildren().add(TitleComponent.builder()
			.text("POH Guests")
			.build());
		panelComponent.getChildren().add(TitleComponent.builder()
			.text(String.valueOf(plugin.getGuestCount()))
			.build());

		return super.render(graphics);
	}
}

